import json
d = json.load(open('sm_github.json'))
def find_rules(obj, path=''):
    if isinstance(obj, dict):
        if 'jql' in obj or 'query' in obj and 'configFile' in obj:
            yield path, obj
        for k, v in obj.items():
            yield from find_rules(v, path + '/' + k)
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            yield from find_rules(v, path + f'[{i}]')
for p, r in find_rules(d):
    print('===', p)
    print(json.dumps(r, indent=1)[:500])
EOF

