function queryIssues(rule, provider, repoInfo, branchPrefix, limit, machineAuthor, owner) {
    var q = rule.query || {};
    var full = repoInfo.owner + '/' + repoInfo.repo;
    var seen = {};
    var items = [];

    // Per-label OR search (GitHub ANDs multi-label queries). Collect ALL
    // matches — the FIFO sort at the end picks the oldest, so an early
    // per-label cut at `limit` would drop old issues behind newer ones.
    // The scans fan out through smAsync: one runAsync worker round when
    // parallelWorkers is wired, the identical sequential order otherwise.
    // Merging iterates descriptor order — labels in rule order, then the
    // assignee scan — and dedupes by number, exactly like the old inline
    // sequence.
    var descriptors = (q.labels || []).map(function (ml) {
        return { kind: 'label', label: ml };
    });
    if (q.assignee) descriptors.push({ kind: 'assignee' });

    var searchOne = function (d) {
        var queryStr = 'repo:' + full + ' is:issue is:open ' +
            (d.kind === 'label' ? 'label:"' + d.label + '"' : 'assignee:' + q.assignee);
        var res = parseMcp(github_search_issues({ query: queryStr }));
        return { descriptor: d, items: asList(res) };
    };

    var searchResults;
    if (descriptors.length > 1) {
        searchResults = smAsyncModule.map(descriptors, ISSUE_SEARCH_WORKER_SOURCE, function (d) {
            return { repo: repoInfo, descriptor: d, assignee: q.assignee };
        });
    } else {
        searchResults = descriptors.map(searchOne);
    }

    searchResults.forEach(function (r) {
        r.items.forEach(function (it) {
            if (seen[it.number]) return;
            seen[it.number] = true;
            var item = {
                key: 'gh-' + it.number,
                labels: issueLabels(it),
                pr: null,
                issueNumber: it.number,
                prNumber: null
            };
            // label-scan items keep the raw payload (today's shape);
            // assignee items never carried it.
            if (r.descriptor.kind === 'label') item._raw = it;
            items.push(item);
        });
    });

    // Linked-PR enrichment: the issue carries the state, the PR carries
    // the CI/merge observation. Multi-item batches fan out through
    // smAsync with ONE cache snapshot fetched up front and shipped to
    // every worker via args.preseed; single-item lists keep today's
    // sequential path with NO snapshot fetch (avoids the extra
    // github_list_branches call for the common single-issue case).
    var enriched;
    if (items.length > 1) {
        var snapshot = (typeof runAsync === 'function' && provider &&
            typeof provider.snapshot === 'function') ? provider.snapshot() : null;
        var enrichResults = smAsyncModule.map(items, ISSUE_ENRICH_WORKER_SOURCE, function (item) {
            return { repo: repoInfo, n: item.issueNumber, prefix: branchPrefix, preseed: snapshot };
        });
        enriched = enrichResults.map(function (r, i) {
            var item = items[i];
            var prRef = r.prRef;
            if (prRef && prRef.state === 'OPEN') {
                item.pr = r.pr;
                item.prNumber = prRef.number;
                item.branch = (item.pr && item.pr.branch) || '';
                // Write-back — same cross-rule memo contract as the
                // queryPrs batch above.
                if (provider && typeof provider.memoPrStatus === 'function') {
                    provider.memoPrStatus(prRef.number, r.pr);
                }
            } else if (prRef) {
                item.pr = { number: prRef.number, state: prRef.state,
                            checks: 'none', mergeState: 'UNKNOWN', mergeable: null };
                item.prNumber = prRef.number;
            }
            return item;
        });
    } else {
        enriched = items.map(function (item) {
            var prRef = provider.findPr(item.issueNumber, branchPrefix);
            if (prRef && prRef.state === 'OPEN') {
                item.pr = provider.prStatus(prRef.number);
                item.prNumber = prRef.number;
                item.branch = (item.pr && item.pr.branch) || '';
            } else if (prRef) {
                item.pr = { number: prRef.number, state: prRef.state,
                            checks: 'none', mergeState: 'UNKNOWN', mergeable: null };
                item.prNumber = prRef.number;
            }
            return item;
        });
    }

    var matched = enriched.filter(function (item) { return matchesGuards(item, rule, provider, machineAuthor, owner, repoInfo); });

/**
 * Unit tests for the poisoned-session quarantine in
 * .github/workflows/factory-teammate.yml.
 *
 * RCA (owner, dmd PR-266, 2026-09-27 — correcting the initial Bitrise-pool
 * theory): each cancelled leg's persist step (always()) SAVED the frozen
 * fa session and the next leg's restore step re-loaded it — three
 * consecutive zombie legs resumed the same poisoned state until the
 * fa-sess/<anchor> branch was deleted by hand. A fresh-session control leg
 * succeeded. The quarantine must therefore (a) trigger only when the leg
 * failed/cancelled AND the trace went silent (a failed leg with an active
 * trace keeps its session — it is the next round's context), (b) move the
 * local store aside so the persist step saves nothing, and (c) DELETE the
 * fa-sess/<anchor> branch — otherwise the next leg restores the poison
 * despite (b).
 *
 * Uses: file_read(), suite(), test(), assert
 */

// #591 moved factory-teammate.yml's canonical home to
// IstiN/dmtools-agentic-workflows — when this checkout carries no local
// copy there is nothing to pin here and the whole suite skips.
var wf = (function () {
    try {
        return file_read({ path: '.github/workflows/factory-teammate.yml' });
    } catch (e) {
        return null;
    }
})();
var q = wf === null ? -1 : wf.indexOf('Quarantine poisoned fa session');

if (wf === null) {
    suite('factory-teammate.yml — poisoned fa session quarantine (SKIPPED: canonical home is dmtools-agentic-workflows, #591)', function () {
        test('no local workflow copy — nothing to pin', function () { assert.ok(true); });
    });
} else {
suite('factory-teammate.yml — poisoned fa session quarantine (owner RCA 2026-09-27)', function () {

    assert.ok(q !== -1, 'quarantine step present');

    test('the Run agent step exposes an id the quarantine can gate on', function () {
        assert.ok(wf.indexOf('Run agent (fa provider via runner env overrides)\n        id: run_agent') !== -1,
            "Run agent carries id: run_agent (steps.run_agent.outcome must be addressable)");
    });

    test('quarantine gates on failure/cancelled of the agent step only', function () {
        assert.ok(wf.indexOf("if: always() && (steps.run_agent.outcome == 'failure' || steps.run_agent.outcome == 'cancelled')") !== -1,
            'fires only when the agent leg itself failed or was cancelled — not on later post-action failures');
    });

    test('a silent trace is the poison marker, with a tunable limit defaulting to 5 min', function () {
        assert.ok(wf.indexOf('FA_TRACE_QUARANTINE_SILENCE_MINUTES:-5') !== -1,
            'silence limit env var with a 5-minute default (healthy fa writes every few seconds)');
        assert.ok(wf.indexOf('age_min=$(( ( $(date +%s) - mtime ) / 60 ))') !== -1,
            'trace mtime age is computed in minutes');
        assert.ok(wf.indexOf('fa trace was active ${age_min} min ago (< ${silence_limit})') !== -1,
            'an ACTIVE trace keeps the session for the retry');
        assert.ok(wf.indexOf('no fa trace — cannot judge session health; leaving the session in place') !== -1,
            'a missing trace is conservative: no quarantine without evidence');
    });

    test('quarantine moves the local store aside AND deletes the fa-sess branch', function () {
        assert.ok(wf.indexOf('mv "${SESS_DIR}" "${QUAR_DIR}"') !== -1,
            'local session store moved out of .dmtools/fa-sessions — the persist step below then early-exits');
        assert.ok(wf.indexOf('git push origin --delete "${FA_SESS_BRANCH}"') !== -1,
            'the fa-sess/<anchor> branch is deleted — without this the next leg restores the poison anyway');
        assert.ok(wf.indexOf('FA-SESSION-QUARANTINE:') !== -1,
            'marker appended to run-output for the SM red-path diagnostics');
    });

    test('the quarantined store ships with the trace artifact', function () {
        assert.ok(wf.indexOf('.dmtools/fa-sessions-quarantine/**') !== -1,
            'artifact upload includes the quarantined session for forensics');
    });

    test('quarantine runs before the trace upload and the persist step', function () {
        var upload = wf.indexOf('Upload the full fa session trace');
        var persist = wf.indexOf('Persist fa session to its git branch');
        assert.ok(q < upload && upload < persist,
            'order: quarantine → artifact upload → persist (persist must find the store already gone)');
    });
});
}

