            var matchesStubName = stubAnchorMatches(runName, ticketKey);
            if (matchesOldName || matchesDisplayName || matchesStubName) {
                console.log('  ⏭️  ' + ticketKey + ' skipped (active workflow already exists: ' + expectedRunName + ')');
