                    { number: 5, labels: [{ name: 'agent:dev' }, { name: 'x' }] }
                ] };
            }
            if (args.query.indexOf('label:"agent:rework"') !== -1) {
                return { items: [{ number: 5, labels: [{ name: 'agent:rework' }] }] };
            }
            return { items: [{ number: 7, labels: [] }] }; // assignee scan
