        }, { repoInfo: { owner: 'a', repo: 'b' }, machineAuthor: 'ai-teammate' });

        assert.equal(queries.length, 1, 'one assignee search descriptor');
        assert.equal(queries[0].indexOf('assignee:ai-teammate') !== -1, true,
