// assignment matched.
var DEV_ON_ASSIGNMENT_RULE = { source: 'github',
    query: { type: 'issue', assignee: '{machineAuthor}', noOpenPr: true },
    workflowFile: 'ai-teammate.yml',
    inputs: { issue: '{issueNumber}', leg: 'dev',
