        }, { repoInfo: { owner: 'a', repo: 'b' }, machineAuthor: 'ai-teammate' });

        assert.deepEqual(items.map(function (i) { return i.key; }), ['gh-402', 'gh-403'],
            'OPEN linked PR excluded; MERGED-PR and PR-less issues stay eligible');
    });

