// run titles carry no number today, and a PR number and an issue number are
// different entities — '#925' must never key a 'pr-925' anchor).
function anchorTokens(ticketKey) {
    var tokens = ['[REDACTED:Sensitive Value]' + ticketKey];
    var m = /^gh-(\d+)$/.exec(ticketKey);
    if (m) tokens.push('#' + m[1]);
    return tokens;
}

function stubAnchorMatches(runName, ticketKey) {
    var tokens = anchorTokens(ticketKey);
    for (var t = 0; t < tokens.length; t++) {
        var token = tokens[t];
        var from = 0;
        while (from <= runName.length - token.length) {
            var idx = runName.indexOf(token, from);
            if (idx === -1) break;
            if (!isAnchorKeyChar(runName.charAt(idx + token.length))) return true;
            from = idx + 1;
        }
    }
    return false;
}
