                    { number: 402, labels: [] },
                    { number: 403, labels: [] }
                ] };
            }
        }, {
            401: { number: 500, state: 'OPEN' },
            402: { number: 501, state: 'MERGED' }
        }, {
            500: { number: 500, state: 'OPEN', checks: 'green', mergeState: 'CLEAN' }
        });
