        assert.equal(r.workflowFile, 'ai-teammate.yml', 'dispatches the factory workflow');
        assert.ok(r.limit >= 1 && r.limit <= 5,
            'bounded per tick — a burst drains over consecutive ticks (workflow budget caps concurrency)');
    });
