// it: a key-extending character (digits/letters extend the number;
// '-' continues a compound key) — that token belongs to a different item.
function isAnchorKeyChar(ch) {
    return (ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'z') ||
