    # error. ls-tree prints nothing for an absent path and stays safe inside
    # the [ -n ] guard even for an unresolvable ref.
    if [ -n "$(git ls-tree --name-only "refs/remotes/origin/$FA_SESS_BRANCH" -- .dmtools/fa-sessions)" ]; then
